package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaViDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujood)", "(Allah là) Đấng Vinh quang nhất, Thánh thiện nhất, Chúa của các thiên thần và Thần linh (Jibril).", "Trong ruku và sujood.", "Nhà tiên tri ﷺ đã đọc điều này bằng ruku và sujood."),
        "dua_sujood_dhanbi_kullah" to DuaText("Trong Sujood: Tha thứ mọi tội lỗi của tôi", "Ôi Allah, hãy tha thứ cho tôi mọi tội lỗi của tôi - nhỏ và lớn, đầu tiên và cuối cùng, công khai và ẩn giấu.", "Trong sujoo.", "Lễ lạy là nơi mà những lời cầu nguyện được đáp lại."),
        "dua_sujood_ridaka" to DuaText("Quy y trong niềm vui của bạn", "Ôi Allah, tôi cầu xin sự hài lòng của Ngài trước cơn giận dữ của Ngài, sự tha thứ của Ngài khỏi sự trừng phạt của Ngài và tôi tìm nơi ẩn náu trong Ngài khỏi Ngài. Tôi không thể ca ngợi Ngài trọn vẹn; Bạn giống như bạn đã ca ngợi chính mình.", "Thật may mắn - Aisha (RA) đã nghe Nhà tiên tri ﷺ nói điều này.", "Một lời khen ngợi của Nhà tiên tri ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Tất cả các hành vi thờ phượng bằng lời nói, thể chất và tài chính đều dành cho Allah. Hỡi Đấng tiên tri, xin bình an và lòng thương xót của Allah và những phước lành của Ngài. Cầu bình an cho chúng ta và những tôi tớ công chính của Allah. Tôi làm chứng rằng không ai có quyền được tôn thờ ngoại trừ Allah và tôi làm chứng rằng Muhammad ﷺ là người hầu và Sứ giả của Ngài.", "Trong mỗi lần ngồi — được thuật lại bởi Abdullah ibn Mas'ud (RA) (thực hành Hanafi).", "Nhà tiên tri ﷺ đã dạy nó giống như một surah của Kinh Qur'an."),
        "dua_sajdah_tilawah" to DuaText("Sajdah của tụng niệm", "Mặt tôi đã phủ phục trước Đấng đã tạo ra nó và tạo ra thính giác và thị giác bằng sức mạnh và quyền năng của Ngài.", "Trong lễ lạy trì tụng.", "Nhà tiên tri ﷺ đã nói điều này trong buổi lễ lạy tụng niệm vào ban đêm."),
        "dua_after_witr" to DuaText("Sau Witr", "Vinh quang thay Đức Vua, Đấng Chí Thánh.", "Ba lần sau salam of witr, lần thứ ba cao giọng.", "Nhà tiên tri ﷺ đã nói điều này sau Witr."),
        "dua_tahajjud_nur" to DuaText("Lời cầu nguyện khai mạc Tahajjud", "Ôi Allah, lời khen ngợi thuộc về Ngài; Bạn là Người duy trì bầu trời, trái đất và tất cả mọi thứ trong đó. Để bạn thuộc về lời khen ngợi; Bạn là Ánh sáng của trời, đất và tất cả mọi thứ trong đó. Để bạn thuộc về lời khen ngợi; Bạn là Sự thật, Lời hứa của Bạn là sự thật, cuộc gặp gỡ với Bạn là sự thật, Lời nói của Bạn là sự thật, Thiên đường là sự thật, Địa ngục là sự thật, Các nhà tiên tri là sự thật, Muhammad ﷺ là sự thật và Giờ là sự thật.", "Khi bắt đầu buổi cầu nguyện ban đêm (tahajjud) (phần mở đầu của dua).", "Nhà tiên tri ﷺ đã kể lại điều này khi nổi lên vì tahajjud (dua đầy đủ ở al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Hướng dẫn tôi trong các vấn đề tranh chấp", "Ôi Allah, Chúa tể của Jibril, Mika'il và Israfil, Người tạo ra thiên đường và trái đất, Người biết về những thứ không thể nhìn thấy và những thứ được nhìn thấy! Bạn sẽ phán xét giữa các tôi tớ của Ngài về những gì họ từng khác nhau. Hãy hướng dẫn tôi với sự cho phép của Ngài về sự thật trong những điều còn khác biệt. Quả thật, Chúa sẽ hướng dẫn ai theo con đường ngay thẳng.", "Khi bắt đầu tahajjud - để được hướng dẫn về sự thật trong bối cảnh bất đồng.", "Nhà tiên tri ﷺ bắt đầu buổi cầu nguyện ban đêm của mình bằng câu nói này."),
        "dua_going_to_mosque_nur" to DuaText("Đi đến nhà thờ Hồi giáo (Dua ánh sáng)", "Lạy Allah, hãy đặt ánh sáng vào trái tim tôi, ánh sáng trong mắt tôi, ánh sáng trong tai tôi, ánh sáng bên phải, ánh sáng bên trái, ánh sáng phía trên tôi, ánh sáng bên dưới tôi, ánh sáng phía trước tôi, ánh sáng phía sau tôi và chiếu sáng cho tôi.", "Trong khi đến nhà thờ Hồi giáo để cầu nguyện cho Fajr.", "Nhà tiên tri ﷺ đã đọc điều này khi ra ngoài cầu nguyện."),
        "dua_waswasa_salah" to DuaText("Waswasa Trong Lễ Salah (Khinzab)", "Tôi cầu xin Allah che chở khỏi Shaytan, kẻ đáng nguyền rủa.", "Khi những lời thì thầm của quỷ Satan vang lên trong lúc cầu nguyện, hãy tìm nơi ẩn náu và nhổ nhẹ sang trái ba lần.", "Uthman ibn Abil-'As (RA) đã làm điều này và những lời thì thầm biến mất."),
        "dua_alimal_ghayb" to DuaText("Người biết điều không thể nhìn thấy", "Ôi Allah, Đấng Biết những điều vô hình và hữu hình, Đấng Tạo Hóa của trời và đất, Chúa và Đấng Tối cao của vạn vật! Tôi làm chứng rằng không có thần nào ngoại trừ Ngài. Con tìm nơi nương tựa nơi Ngài khỏi cái ác của chính con, và khỏi cái ác của Shaytan và sự trốn tránh (lời kêu gọi) của hắn.", "Buổi sáng, buổi tối và trước khi ngủ - Nhà tiên tri ﷺ đã dạy điều đó cho Abu Bakr (RA).", "Bảo vệ khỏi cái ác của bản thân và của Shaytan."),
        "dua_fitratil_islam" to DuaText("Theo Fitrah của đạo Hồi", "Chúng ta đã bước vào buổi sáng theo fitrah của đạo Hồi, theo lời nói chân thành, theo tôn giáo của Nhà tiên tri Muhammad ﷺ của chúng ta và theo con đường của cha chúng ta là Ibrahim (AS), người ngay thẳng và là một người theo đạo Hồi, và không theo những người theo đạo đa thần.", "Vào buổi sáng.", "Canh tân đức tin mỗi sáng."),
        "dua_amsayna_fitrah" to DuaText("Buổi tối trên Fitrah của đạo Hồi", "Chúng ta đã bước vào buổi tối dựa trên fitrah của đạo Hồi, dựa trên lời nói chân thành, dựa trên tôn giáo của Nhà tiên tri Muhammad ﷺ của chúng ta và theo con đường của cha chúng ta là Ibrahim (AS), người ngay thẳng và là một người theo đạo Hồi, và không theo những người theo đạo đa thần.", "Vào buổi tối.", "Canh tân đức tin mỗi tối."),
        "dua_tahleel_10_fajr" to DuaText("Mười Tahleel Sau Fajr và Maghrib", "Không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác. Ngài là quyền thống trị và Ngài là sự khen ngợi; Ngài ban sự sống và gây ra cái chết, và Ngài có quyền trên mọi sự.", "Mười lần sau Fajr (và Maghrib), trước khi rời khỏi chỗ ngồi hoặc nói chuyện.", "Mười việc tốt, mười tội được xóa, mười cấp tăng và bảo vệ khỏi Shaytan cả ngày."),
        "dua_la_hawla_kanz" to DuaText("Kho báu của Jannah", "Không có sức mạnh và quyền lực nào ngoại trừ Allah.", "Thường xuyên, mọi lúc.", "Đó là một trong những kho báu của Thiên đường."),
        "dua_four_beloved_words" to DuaText("Bốn chữ yêu quý nhất", "Vinh quang thay Allah, mọi lời ca ngợi đều dành cho Allah, không ai có quyền được tôn thờ ngoại trừ Allah và Allah là Đấng Vĩ đại nhất.", "Những lời yêu quý nhất đối với Allah.", "Đối với Nhà tiên tri ﷺ, họ quý giá hơn mọi thứ mà mặt trời mọc."),
        "dua_two_light_words" to DuaText("Hai chữ nhẹ trên đầu lưỡi", "Vinh quang thay Allah và mọi lời khen ngợi đều thuộc về Ngài; vinh quang thay Allah, Đấng Vĩ Đại.", "Nhẹ ở lưỡi, nặng ở âm giai.", "Được Đấng Nhân Từ yêu quý nhất, nhẹ nhàng trên lưỡi và nặng nề trên Cân. (hadith cuối cùng của al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "Hỡi người sở hữu uy nghiêm và danh dự!", "Hãy giữ vững điều đó - lời chỉ dẫn ﷺ của Nhà tiên tri.", "Nhà tiên tri ﷺ đã nói: hãy giữ lấy 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("Nhân danh em anh nằm xuống", "Nhân danh Chúa, lạy Chúa, con nằm xuống và nhân danh Chúa, con trỗi dậy. Nếu Chúa lấy đi linh hồn con, xin thương xót nó, và nếu Chúa thả nó ra, xin hãy bảo vệ nó như Chúa bảo vệ những tôi tớ công chính của Ngài.", "Sau khi phủi bụi trên giường và nằm xuống.", "Hãy giao phó linh hồn của mình cho Allah trước khi ngủ."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Bạn đã tạo ra tâm hồn tôi", "Ôi Allah, Ngài đã tạo ra linh hồn của tôi và Ngài sẽ lấy nó. Cái chết và sự sống của nó thuộc về Bạn. Nếu Ngài giữ nó sống, hãy bảo vệ nó, và nếu Ngài làm nó chết, hãy tha thứ cho nó. Ôi Allah, tôi cầu xin Ngài sự an lành.", "Trước khi ngủ — được thuật lại bởi Ibn Umar (RA).", "Nhà tiên tri ﷺ đã hướng dẫn nói điều này trước khi đi ngủ."),
        "dua_sleep_atamana" to DuaText("Tri Ân Trước Khi Ngủ", "Mọi lời khen ngợi đều dành cho Allah, Đấng đã cho chúng tôi ăn, cho chúng tôi uống, đủ no và cho chúng tôi nơi trú ẩn. Có bao nhiêu người không có ai che chở hoặc cho họ chỗ ở.", "Khi đi ngủ.", "Nhà tiên tri ﷺ đã nói điều này khi đi ngủ."),
        "dua_sleep_rabbas_samawat" to DuaText("Chúa Trời - Trả nợ cho chúng tôi", "Ôi Allah, Chúa của các tầng trời, trái đất và ngai vàng hùng mạnh, Chúa của chúng ta và Chúa của vạn vật, Người phân chia hạt giống và đá chà là, Người tiết lộ Kinh Torah, Injil và Furqan! Tôi tìm nơi ẩn náu trong Bạn khỏi sự xấu xa của mọi thứ mà bạn nắm giữ. Ôi Allah, Ngài là Đấng đầu tiên, không có gì trước Ngài; Bạn là Người cuối cùng, không có gì sau Bạn; Bạn là Đấng Biểu hiện, không có gì ở trên Bạn; Bạn là Người ẩn giấu, không có gì ẩn giấu khỏi Bạn. Hãy giải quyết nợ nần cho chúng tôi và giải thoát chúng tôi khỏi nghèo đói.", "Trước khi ngủ, nằm nghiêng bên phải — được dạy cho Fatimah (RA).", "Một du mục để thoát khỏi nợ nần và khó khăn."),
        "dua_sleep_fear" to DuaText("Sợ hãi hoặc khó chịu trong giấc ngủ", "Tôi tìm nơi ẩn náu trong những lời nói hoàn hảo của Allah để tránh cơn giận dữ và sự trừng phạt của Ngài, khỏi sự xấu xa của các tôi tớ của Ngài và khỏi những lời thì thầm của ma quỷ và khỏi việc chúng đến với tôi.", "Khi cảm thấy sợ hãi hoặc khó chịu trong giấc ngủ.", "Làm như vậy thì vật đó sẽ không làm hại được anh ta."),
        "dua_waking_afani" to DuaText("Thức tỉnh: Anh ấy đã phục hồi tâm hồn tôi", "Mọi lời khen ngợi đều dành cho Allah, người đã ban cho cơ thể tôi khỏe mạnh, trả lại linh hồn cho tôi và cho phép tôi nhớ đến Ngài.", "Khi thức dậy.", "Tri ân một buổi sáng mới."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah là Chúa của tôi", "Allah, Allah là Chúa của tôi; Tôi không liên kết bất cứ điều gì với Ngài.", "Trong đau buồn hay đau khổ — Nhà tiên tri ﷺ đã dạy điều đó cho Asma bint Umays (RA).", "Giữ lấy tawhis trong lúc khó khăn."),
        "dua_rahmataka_arju" to DuaText("Lòng Thương Xót của Ngài Con Hy Vọng", "Ôi Allah, tôi hy vọng vào lòng thương xót của Ngài, vì vậy đừng bỏ mặc tôi dù chỉ trong chớp mắt và hãy sắp xếp mọi công việc của tôi. Không có thần nào ngoại trừ Bạn.", "Dua của người gặp nạn (Da'awat al-makrub).", "Nhà tiên tri ﷺ gọi đó là dua của người gặp nạn."),
        "dua_against_enemy_ahzab" to DuaText("Chống lại quân địch", "Ôi Allah, Người tiết lộ cuốn sách, Nhanh chóng tính toán! Đánh bại quân liên minh. Ôi Allah, hãy đánh bại chúng và lay chuyển chúng.", "Chống lại kẻ thù - trận chiến của quân miền Nam.", "ﷺ của Nhà tiên tri chống lại kẻ thù."),
        "dua_anta_adudi" to DuaText("Bạn là sự hỗ trợ của tôi", "Ôi Allah, Bạn là người hỗ trợ và trợ giúp của tôi. Nhờ Bạn mà tôi lên kế hoạch, nhờ Bạn mà tôi thăng tiến và nhờ Bạn mà tôi chiến đấu.", "Trước một cuộc thi hoặc một thử thách lớn.", "Nhà tiên tri ﷺ đã nói điều này trong trận chiến."),
        "dua_ikfinihim" to DuaText("Đủ cho tôi chống lại họ", "Ôi Allah, đủ để con chống lại chúng dù Ngài muốn thế nào đi nữa.", "Chống lại cái ác của những kẻ áp bức - dua của cậu bé trong truyện Người dân vùng mương.", "Allah đã cứu cậu bé khỏi những kẻ áp bức."),
        "dua_qadarullah" to DuaText("Khi điều gì đó tồi tệ xảy ra", "Đó là mệnh lệnh của Allah và Ngài đã làm những gì Ngài muốn.", "Khi có điều gì đó khó chịu xảy ra, thay vì nói “giá như”.", "'Giá như' mở ra cánh cửa cho Shaytan."),
        "dua_ala_kulli_hal" to DuaText("Khen ngợi trong mọi tình huống", "Mọi lời khen ngợi đều dành cho Allah trong mọi tình huống.", "Khi điều gì đó không thích xảy ra.", "Nhà tiên tri ﷺ đã nói điều này khi đối mặt với điều gì đó mà ông ấy không thích."),
        "dua_dogs_barking" to DuaText("Nghe tiếng chó sủa vào ban đêm", "Tôi cầu xin Allah che chở khỏi Shaytan, kẻ đáng nguyền rủa.", "Khi nghe tiếng chó sủa hoặc tiếng lừa kêu vào ban đêm.", "Họ nhìn thấy những gì bạn không nhìn thấy."),
        "dua_leaving_home_adilla" to DuaText("Trốn tránh sự lạc lối", "Ôi Allah, tôi cầu xin Ngài che chở kẻo tôi đi lạc hoặc bị dẫn đi lạc lối, kẻo tôi trượt chân hoặc bị làm cho trượt chân, kẻo tôi làm điều sai trái hoặc bị đối xử bất công, kẻo tôi cư xử ngu ngốc hoặc bị đối xử ngu ngốc.", "Khi rời khỏi nhà — do Umm Salamah (RA) thuật lại.", "Nhà tiên tri ﷺ đã đọc điều này bất cứ khi nào ông rời khỏi nhà."),
        "dua_ascending_descending" to DuaText("Đi lên và đi xuống", "Allah là Đấng vĩ đại nhất (khi đi lên). — Vinh quang thay Allah (khi đi xuống).", "Trên đường đi, hãy nói 'Allahu Akbar' khi đi lên và 'SubhanAllah' khi đi xuống.", "Sự thực hành của Người Bạn Đồng Hành (RA) khi đi du lịch."),
        "dua_traveller_sahar" to DuaText("Dua của lữ khách trước bình minh", "Một thính giả đã nghe (và truyền lại) lời khen ngợi của chúng tôi về Allah và những ân huệ tốt đẹp của Ngài dành cho chúng tôi. Lạy Chúa, xin hãy đồng hành cùng chúng tôi và ban ân huệ của Ngài cho chúng tôi - (tôi nói điều này) đang tìm nơi ẩn náu nơi Allah khỏi Lửa.", "Trên một cuộc hành trình, trước bình minh.", "Nhà tiên tri ﷺ đã nói điều này trước bình minh khi đi du lịch."),
        "dua_zawwadakallah" to DuaText("Gửi đến khách du lịch: Cầu mong Allah cung cấp Taqwa", "Cầu mong Allah cung cấp cho bạn taqwa cho cuộc hành trình của bạn, tha thứ cho tội lỗi của bạn và tạo điều kiện thuận lợi cho bạn mọi lúc mọi nơi.", "Khi chia tay một lữ khách.", "Nhà tiên tri ﷺ đã đưa dua này cho một người nào đó đang bắt đầu một cuộc hành trình."),
        "dua_traveller_to_resident" to DuaText("Lữ khách của những người ở lại phía sau", "Tôi giao phó bạn cho Allah, Đấng mà niềm tin không bao giờ mất đi.", "Câu nói của lữ khách khi chia tay gia đình.", "Giao phó sự an toàn của gia đình cho Allah."),
        "dua_entering_village" to DuaText("Vào một thị trấn hoặc làng", "Ôi Allah, Chúa tể của bảy tầng trời và tất cả chúng che phủ, Chúa tể của bảy trái đất và tất cả những gì chúng mang theo, Chúa tể của quỷ dữ và tất cả chúng lầm lạc, Chúa tể của gió và tất cả chúng phân tán! Chúng con cầu xin Ngài cho điều tốt lành của thị trấn này cũng như điều tốt lành của người dân nơi đây, và chúng con cầu xin Ngài nương náu nơi Ngài khỏi cái ác của nó, cái ác của người dân nó và cái ác của những gì ở trong đó.", "Trước khi vào một thị trấn hoặc thành phố.", "Nhà tiên tri ﷺ đã kể lại điều này bất cứ khi nào ông ấy muốn vào một thị trấn."),
        "dua_vehicle_stumbles" to DuaText("Khi xe bị vấp ngã", "Nhân danh Allah.", "Khi thú cưỡi hoặc xe bị trượt hoặc vấp ngã, thay vì nói 'Cầu mong Shaytan bị diệt vong'.", "Nói Bismillah khiến Shaytan co lại thành kích thước của một con ruồi."),
        "dua_ajz_kasal_haram" to DuaText("Quy y sự yếu đuối và tuổi già", "Ôi Allah, tôi cầu xin Ngài che chở khỏi sự bất lực và lười biếng, khỏi sự hèn nhát và tuổi già, khỏi những thử thách của sự sống và cái chết, và khỏi sự trừng phạt của nấm mộ.", "Một sự quy y toàn diện hàng ngày.", "A dua the Prophet ﷺ được thực hiện thường xuyên."),
    )
}
